import argparse
import json
import sys
from input_rules import validate_quantity


def execute(operation, request):
    if operation not in ("submit", "replay"):
        raise ValueError("unknown operation")
    if operation == "replay":
        return {"operation": operation, "quantity": request["quantity"]}
    return {"operation": operation, "quantity": validate_quantity(request)}


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("operation", choices=("submit", "replay"))
    parser.add_argument("request")
    args = parser.parse_args()
    try:
        result = execute(args.operation, json.loads(args.request))
    except (ValueError, TypeError, KeyError):
        print("invalid request", file=sys.stderr)
        return 2
    print(json.dumps(result, sort_keys=True))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

