import json
import os
from pathlib import Path
import subprocess
import sys
import unittest
from service import execute

ROOT = Path(__file__).resolve().parent


def cli(operation, raw):
    return subprocess.run([sys.executable, "-B", str(ROOT / "service.py"), operation, raw],
                          cwd=ROOT, capture_output=True, text=True, env=dict(os.environ, PYTHONDONTWRITEBYTECODE="1"))


class ServiceTests(unittest.TestCase):
    def test_submit_valid_cli(self):
        result = cli("submit", '{"quantity": 3}')
        self.assertEqual(0, result.returncode, result.stderr)
        self.assertEqual({"operation": "submit", "quantity": 3}, json.loads(result.stdout))

    def test_replay_valid_api(self):
        self.assertEqual({"operation": "replay", "quantity": 3}, execute("replay", {"quantity": 3}))

    def test_submit_zero_refused(self):
        result = cli("submit", '{"quantity": 0}')
        self.assertEqual(2, result.returncode)
        self.assertEqual("", result.stdout)
        self.assertEqual("invalid request\n", result.stderr)

    def test_submit_nonobject_refused(self):
        self.assertEqual(2, cli("submit", '[]').returncode)

    def test_malformed_json_refused(self):
        self.assertEqual(2, cli("submit", '{').returncode)

    def test_unknown_operation(self):
        with self.assertRaisesRegex(ValueError, "unknown operation"):
            execute("other", {"quantity": 3})


if __name__ == "__main__":
    unittest.main()

